import { dungeonView } from './exploration.js';
import { radiantView } from './radiant-descent.js';
import { rpgView } from './rpg-depth-v27.js';
import { passageDirection } from './dungeon-directions.js';
import { renderSpatialCommit } from './spatial-controls.js';
import { renderAreaScene } from './area-scenes.js';
import { getActions } from './engine.js';
export function dungeonPresentation(s){
 const actions=getActions(s),x=s.rpg?.expedition;
 if(x){const current=x.rooms.find(r=>r.id===x.roomId),known=x.rooms.filter(r=>r.visited||current.neighbors.includes(r.id));return {kind:'rpg',title:x.title,room:current.title,description:current.description||'Old passages lead away from this chamber.',rooms:known.map(r=>({...r,current:r.id===current.id,label:r.visited?r.title:passageDirection(s.seed,x.id,current,r)})),exits:known.filter(r=>current.neighbors.includes(r.id)).map(r=>({id:r.id,label:r.visited?r.title:passageDirection(s.seed,x.id,current,r),visited:r.visited})),actions:rpgView(s).actions,visited:x.rooms.filter(r=>r.visited).length,goal:x.completed?'Your work here is complete. You can retrace your route or leave the descent.':x.purpose||'Explore the passages, attend to the people you find, and return with what you earn.'};}
 const radiant=radiantView(s);
 if(radiant){const current=radiant.rooms.find(r=>r.id===radiant.current),routes=(s.event?.id==='adventure_room'?s.event.choices:[]).filter(c=>c.id.startsWith('route_'));return {kind:'dungeon',title:'The '+s.adventuring.expedition.theme+' Descent',room:current?.title||'The Current Chamber',description:current?.resolved?'Your earlier work in this room remains. Choose a doorway to continue.':'You stand inside a chamber beneath the surface.',floor:radiant.floor,rooms:radiant.rooms.map(r=>({...r,id:'radiant_'+r.id,current:r.id===radiant.current,neighbors:r.neighbors.map(n=>'radiant_'+n)})),exits:routes.map(c=>{const r=radiant.rooms.find(r=>String(r.id)===c.id.slice(6));return {id:'radiant_'+c.id.slice(6),label:r?.label||c.label,visited:r?.visited,disabledReason:c.disabledReason};}),actions,visited:radiant.rooms.filter(r=>r.visited).length,goal:radiant.goal.description,completed:radiant.completed};}
 const d=dungeonView(s);
 if(d){const current=d.rooms.find(r=>r.current),routes=(s.event?.choices||[]).filter(c=>c.id.startsWith('route_'));const exits=d.rooms.filter(r=>!r.current&&(current?.exits.includes(r.id)||routes.some(c=>c.id==='route_'+r.id)));return {kind:'dungeon',title:d.title,room:d.room.title,description:d.room.description,rooms:d.rooms.map(r=>({...r,x:r.mapIndex%3,y:Math.floor(r.mapIndex/3),neighbors:r.exits,label:r.title,resolved:r.cleared})),exits:exits.map(r=>({id:r.id,label:r.title,visited:r.visited,disabledReason:routes.find(c=>c.id==='route_'+r.id)?.disabledReason})),actions,visited:d.rooms.filter(r=>r.visited).length,goal:d.objective?.description||d.description,completed:d.complete};}
 const old=s.adventuring?.expedition;
 if(old)return {kind:'dungeon',title:'The '+old.theme+' Descent',room:'Chamber '+(old.room+1),description:'The chamber and its unfinished work remain where you left them.',rooms:[],exits:[],actions,visited:old.cleared.length,floor:old.floor,goal:'Continue or withdraw from the saved descent.'};
 return null;
}
function dungeonMap(v,ui){
 const {e}=ui,rooms=v.rooms,ids=new Set(rooms.map(r=>r.id)),point=r=>[54+(r.x||0)*90,48+(r.y||0)*85],width=Math.max(280,...rooms.map(r=>point(r)[0]+100)),height=Math.max(180,...rooms.map(r=>point(r)[1]+58));
 const edges=rooms.flatMap(r=>r.visited?(r.neighbors||[]).filter(id=>ids.has(id)&&(String(r.id)<String(id)||!rooms.find(n=>n.id===id).visited)).map(id=>{const a=point(r),b=point(rooms.find(n=>n.id===id));return `<path d="M${a.join(' ')}L${b.join(' ')}"/>`;}):[]).join('');
 return `<details class="dungeon-pocket-map" data-disclosure="dungeon-pocket-map"><summary>Your Dungeon Map · ${v.visited} Explored</summary><svg viewBox="0 0 ${width} ${height}" role="group" aria-label="Discovered Dungeon Rooms"><g class="dungeon-map-paths">${edges}</g>${rooms.map(r=>{const p=point(r);return `<g role="button" tabindex="0" data-op="dungeon-select" data-id="${e(r.id)}" aria-label="${e(r.label)}" aria-describedby="spatial-map-help" class="${r.current?'current':''}"><circle cx="${p[0]}" cy="${p[1]}" r="15"/><text x="${p[0]}" y="${p[1]+5}" text-anchor="middle">${r.current?'◆':r.resolved?'✓':r.visited?'◇':'?'}</text><text x="${p[0]}" y="${p[1]+32}" text-anchor="middle" class="dungeon-map-caption">${e(r.label.length>25?r.label.slice(0,23)+'…':r.label)}</text></g>`;}).join('')}</svg></details>`;
}
export function renderDungeonCrawler(s,ui,{encounter='',selectedId=null}={}){
 const v=dungeonPresentation(s);if(!v)return '';const {e,button,actionCards}=ui,selected=v.rooms.find(r=>r.id===selectedId);
 const doors=v.exits.map((exit,i)=>`<button type="button" class="dungeon-door ${exit.id===selectedId?'selected':''}" data-op="dungeon-select" data-id="${e(exit.id)}" aria-pressed="${exit.id===selectedId}" aria-describedby="spatial-map-help" style="--door-position:${(i+1)/(v.exits.length+1)*100}%"><span class="door-arch" aria-hidden="true"><span>${exit.visited?'◇':'?'}</span></span><strong>${e(exit.label)}</strong><small>${exit.visited?'A Known Passage':'Beyond This Door'}</small></button>`).join('');
 const roomActions=v.actions.filter(a=>v.kind==='rpg'?a.id.startsWith('rpg_room_')||a.id.startsWith('rpg_boss_')||a.id==='rpg_leave':a.id.startsWith('explore_')&&!a.id.startsWith('explore_route_')||['adventure_continue','adventure_withdraw'].includes(a.id));
 const finalControls=encounter||actionCards(roomActions);
 const party=[{name:s.hero.name,hp:s.hero.hp,maxHp:s.hero.maxHp},...s.companions.filter(p=>p.recruited&&p.active).map(p=>({name:p.name,hp:p.hp,maxHp:p.maxHp}))];
 return `<div class="dungeon-crawler" data-dungeon-kind="${v.kind}"><header class="dungeon-heading"><div><span class="eyebrow">${e(v.title)}${v.floor?' · Floor '+v.floor:''}</span><h1>${e(v.room)}</h1></div>${button('Journal','tab','quests','ghost small')}${button('Inventory','tab','inventory','ghost small')}</header><div class="dungeon-room-stage">${renderAreaScene(s,ui,{dungeon:{room:{title:v.room}}})}<svg class="dungeon-perspective" viewBox="0 0 1000 460" preserveAspectRatio="none" aria-hidden="true"><path class="dungeon-left-wall" d="M0 0 205 100V340L0 460Z"/><path class="dungeon-right-wall" d="m1000 0-205 100v240l205 120Z"/><path class="dungeon-floor" d="m0 460 205-120h590l205 120Z"/><path class="dungeon-ceiling" d="m0 0 205 100h590L1000 0Z"/><path class="dungeon-stone-lines" d="M0 90 205 160M0 205 205 235M0 330 205 300M1000 90 795 160M1000 205 795 235M1000 330 795 300M80 0 265 100M920 0 735 100M80 460 265 340M920 460 735 340M0 380h1000"/></svg><div class="dungeon-doors">${doors||`<div class="dungeon-sealed"><span>◆</span><strong>${encounter?'Attend to This Room':'A Moment to Look Around'}</strong></div>`}</div></div><div class="dungeon-travel-strip"><span>${v.visited} Rooms Explored</span><span>${s.hero.potions} Potions</span>${s.adventuring?.expedition?`<span>${s.adventuring.rations} Rations</span>`:''}<span>${v.completed?'Objective Complete':'Exploration in Progress'}</span></div><p id="spatial-map-help" class="small-copy">Inspect a doorway with click, Enter or Space, then choose its separate travel command. Double-click follows an available doorway. Unseen rooms keep their contents hidden.</p>${selectedId?`<section class="dungeon-door-inspection"><h2 id="spatial-selection-title" tabindex="-1" aria-describedby="spatial-selection-details">${e(selected?.label||v.exits.find(r=>r.id===selectedId)?.label||'No Visible Doorway')}</h2>${selected||v.exits.some(r=>r.id===selectedId)?renderSpatialCommit(s,v.kind,selectedId,v.actions,ui):'<p id="spatial-selection-details">That doorway is not visible from this room.</p>'}</section>`:''}<section class="dungeon-room-account"><p>${e(v.description)}</p>${finalControls}</section><footer class="dungeon-party-strip" aria-label="Traveling Party">${party.map(p=>`<div><strong>${e(p.name)}</strong>${Number.isFinite(p.hp)&&Number.isFinite(p.maxHp)?`<span>Health ${p.hp}/${p.maxHp}</span>`:'<span>Traveling With You</span>'}</div>`).join('')}</footer><details class="dungeon-objective" data-disclosure="dungeon-objective"><summary>Your Purpose Here${v.completed?' · Complete':''}</summary><p>${e(v.goal)}</p></details>${dungeonMap(v,ui)}</div>`;
}
